SELECT DATE(executed_at) AS d, side, COUNT(*) AS n FROM crypto_ai.wallet_trade WHERE executed_at >= '2026-10-12 00:00:00' GROUP BY DATE(executed_at), side ORDER BY d, side;
SELECT HOUR(generated_at) AS h, COUNT(*) AS n, ROUND(AVG(TIMESTAMPDIFF(MICROSECOND, candle_open_time + INTERVAL 1 MINUTE, generated_at))/1e6,3) AS avg_gen_s, ROUND(MAX(TIMESTAMPDIFF(MICROSECOND, candle_open_time + INTERVAL 1 MINUTE, generated_at))/1e6,3) AS max_gen_s FROM crypto_ai.trade_signal WHERE interval_code='1m' AND generated_at BETWEEN '2026-10-12 00:00:00' AND '2026-10-13 00:00:00' GROUP BY HOUR(generated_at) ORDER BY h;